/* Dated water observations: never use forecasts or terrain colors as flood extent. */
window.ObservedFlood=(()=>{
  const el=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let map,cities=[],metadata=null,lastSuccess=null,error='',pending=null,source='radar',date='',datePinned=false,layer,coverage,exclusion,tiles='not loaded',coverageTiles='not loaded',exclusionTiles='not loaded',cityIndex=0,point=null,pointToken=0,paintToken=0;
  const AGE=2*60*60*1000,utcDay=()=>new Date().toISOString().slice(0,10);
  function product(){return metadata?.[source]}
  function validDate(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value}
  function state(){return{source,date,datePinned,metadata,lastSuccess,error,tiles,coverageTiles,exclusionTiles,enabled:!!el('layer-observed')?.checked,coverageEnabled:source==='radar'&&!!el('layer-observed-coverage')?.checked,exclusionEnabled:source==='radar'&&!!el('layer-observed-exclusion')?.checked,stale:!!lastSuccess&&(Date.now()-Date.parse(lastSuccess)>AGE||!!metadata?.stale||!!error)}}
  function drawStatus(){const p=product(),s=state(),node=el('observed-status');if(!node)return;
    if(!p?.available||!date){node.textContent=error||p?.error||'Observation product or its dated coverage is unavailable. No current flood extent is inferred.';return}
    const partial=date===utcDay()?' · current day, coverage incomplete':'';
    const oldDays=Math.floor((Date.parse(utcDay()+'T00:00:00Z')-Date.parse(date+'T00:00:00Z'))/86400000),historical=oldDays>2?` · ${oldDays} days old; flood conditions may have changed`:'';
    const period=source==='nasa'?`3-day composite ending ${date} (includes the previous two UTC days)`:`Radar acquisitions on ${date} UTC`;
    node.innerHTML=`<b>${esc(p.provider||metadata.provider)} · ${esc(period)}${esc(partial)}${esc(historical)}</b><p>${datePinned?'Selected date · held for comparison':'Following latest available completed UTC day'} · ${esc(p.resolutionM)} m product resolution · ${s.enabled?esc(tiles):'water layer hidden'}${s.coverageEnabled?' · coverage '+esc(coverageTiles):''}${s.exclusionEnabled?' · exclusion mask '+esc(exclusionTiles):''}${s.stale?' · STALE / last known metadata':''}</p><small>Latest source product date: ${esc(p.sourceTimeDefault||'unavailable')} · API checked ${esc(lastSuccess||'unavailable')}${error?' · '+esc(error):''}. Product date does not guarantee this location was observed.</small>`;
  }
  function legend(){const p=product();if(!el('observed-legend'))return;const notes=source==='radar'?[{color:'#e84c78',label:'Radar-detected flood water'},{color:'linear-gradient(90deg,#70ae30 50%,#ed0b01 50%)',label:'Dotted radar scene coverage · not floodwater'}]:[{color:'#fa1e24',label:'Flood detected'},{color:'#ffff00',label:'Recurring flood water'},{color:'#32d2f5',label:'Reference surface water · not new flooding'},{color:'#afafaf',label:'Insufficient observations · unknown'}];
    el('observed-legend').innerHTML=notes.map(n=>`<span><i style="background:${n.color}"></i>${esc(n.label)}</span>`).join('')+`<p>Blank areas: no displayed flood classification or no observation; neither proves dry conditions. ${source==='nasa'?'Zooming enlarges pixels; it does not add street-level detail.':'Radar may miss urban floods, dense vegetation and water outside its valid detection mask.'}</p>${source==='radar'?'<p>Exclusion mask: source pixels that cannot be reliably classified. This quality layer is not flood extent.</p>':''}${p?`<a href="${esc(p.sourceUrl||metadata.sourceUrl)}" target="_blank" rel="noopener">Product &amp; limits ↗</a>`:''}`;
  }
  function removeLayers(){for(const target of [layer,coverage,exclusion])if(target)map?.removeLayer(target);layer=coverage=exclusion=null}
  function dates(p=product()){return Array.isArray(p?.availableDates)?[...new Set(p.availableDates.filter(d=>validDate(d)&&d<=utcDay()))]:[]}
  function controls(){const p=product(),available=dates();if(!available.includes(date))datePinned=false;if(!datePinned){const completed=available.filter(d=>d<utcDay()).sort();date=available.includes(p?.timeDefault)&&p.timeDefault<utcDay()?p.timeDefault:completed.at(-1)||available.slice().sort().at(-1)||''}const select=el('observed-date');if(select){select.innerHTML=available.slice().sort().reverse().map(d=>`<option value="${d}">${d}${d===utcDay()?' · partial today':''}</option>`).join('');select.value=date;select.disabled=!p?.available||!available.length}if(el('coverage-toggle'))el('coverage-toggle').hidden=source!=='radar';if(el('exclusion-toggle'))el('exclusion-toggle').hidden=source!=='radar';if(el('layer-observed-exclusion'))el('layer-observed-exclusion').disabled=source!=='radar'||!p?.available||!p?.exclusionLayerId;if(el('observed-source')){el('observed-source').value=source;for(const o of el('observed-source').options)o.disabled=!metadata?.[o.value]?.available}}
  function tileState(kind,value){if(kind==='coverage')coverageTiles=value;else if(kind==='exclusion')exclusionTiles=value;else tiles=value}
  function track(target,kind='water'){let failed=false;const token=paintToken;target.on('loading',()=>{if(token!==paintToken)return;failed=false;tileState(kind,'loading');drawStatus()});target.on('tileerror',()=>{if(token!==paintToken)return;failed=true;tileState(kind,'some tiles unavailable');drawStatus()});target.on('load',()=>{if(token!==paintToken)return;if(!failed)tileState(kind,'source tiles loaded');drawStatus()});return target}
  function paint(){paintToken++;pointToken++;removeLayers();controls();legend();const p=product();tiles=coverageTiles=exclusionTiles='not loaded';if(!map||!p?.available||!date){if(el('observed-point'))el('observed-point').textContent='Observation coverage unavailable for this selection.';drawStatus();return}
    if(source==='radar'){
      const time=`${date}T00:00:00Z/${date}T23:59:59Z`,opts={format:'image/png',transparent:true,version:'1.1.1',time,pane:'observedPane',maxZoom:18,opacity:1,attribution:'Observed water: Copernicus CEMS Global Flood Monitoring'};
      layer=track(L.tileLayer.wms(p.wmsUrl,{...opts,layers:p.layerId}));
      if(p.coverageLayerId)coverage=track(L.tileLayer.wms(p.wmsUrl,{...opts,layers:p.coverageLayerId,pane:'observedCoveragePane',opacity:.22}),'coverage');
      if(p.exclusionLayerId)exclusion=track(L.tileLayer.wms(p.wmsUrl,{...opts,layers:p.exclusionLayerId,pane:'observedMaskPane',opacity:.45}),'exclusion');
    }else layer=track(L.tileLayer(p.wmtsUrlTemplate.replace('{date}',date),{pane:'observedPane',maxNativeZoom:p.maxNativeZoom||9,maxZoom:18,opacity:1,attribution:'Observed water: NASA LANCE / GIBS'}));
    if(coverage&&el('layer-observed-coverage')?.checked)coverage.addTo(map);if(exclusion&&el('layer-observed-exclusion')?.checked)exclusion.addTo(map);if(el('layer-observed')?.checked)layer.addTo(map);drawStatus();inspectCity();
  }
  async function refresh(){if(pending)return pending;if(!/^https?:$/.test(location.protocol)){error='Start the local server to receive live observed-water metadata and coverage dates.';drawStatus();return}
    pending=(async()=>{try{const r=await fetch('/api/observed-flood',{cache:'no-store',signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error(`Observation API HTTP ${r.status}`);const d=await r.json();if(!d.radar?.available&&!d.nasa?.available)throw Error('Neither observation product is available');metadata=d;lastSuccess=d.fetchedAt||new Date().toISOString();error=d.error||'';if(!metadata[source]?.available)source=metadata.radar?.available?'radar':'nasa';paint()}catch(e){error='Observation refresh failed: '+e.message;drawStatus()}finally{pending=null}})();return pending;
  }
  async function inspect(lat,lon){point={lat,lon};const token=++pointToken,node=el('observed-point');if(!node)return;if(!Number.isFinite(lat)||!Number.isFinite(lon)){node.textContent='Choose a valid map point to check radar observation coverage.';return}if(source!=='radar'){node.textContent='NASA layer: interpret the colored satellite pixels and the gray unknown mask. No point-level flood conclusion is inferred.';return}if(!metadata?.radar?.available||!date||!/^https?:$/.test(location.protocol)){node.textContent='Radar observation coverage unavailable for this point.';return}
    node.textContent=`Checking radar coverage at ${lat.toFixed(5)}, ${lon.toFixed(5)} on ${date}…`;
    try{const q=new URLSearchParams({lat,lon,date}),r=await fetch('/api/observed-point?'+q,{cache:'no-store',signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error(`HTTP ${r.status}`);const d=await r.json();if(token!==pointToken)return;const available=d&&typeof d==='object'&&d.available!==false&&['observed','no-recent-scene','none'].includes(d.coverage),covered=available&&d.coverage==='observed',classification=covered?d.pixel?.classification:'unknown';
      const label=!available?'Water status unknown · Radar coverage query unavailable':classification==='flood-detected'?'Satellite flood classification detected at this point':classification==='reference-water'?'Reference surface water · not evidence of new flooding':classification==='no-flood-detected'?'No flood water classified at this point · verify locally':covered?'Water status unknown · Radar scene covers this point at the selected date':'Water status unknown · No recent radar scene returned for this point';
      node.innerHTML=`<b>${esc(label)}</b><p>${esc(lat.toFixed(5))}, ${esc(lon.toFixed(5))} · ${esc(date)} UTC${d?.latestSensingDate?' · latest acquisition '+esc(d.latestSensingDate):''}<br>${esc(d?.note||'Coverage alone does not establish whether land is flooded. No detection is not proof of safety.')}</p>`;
    }catch(e){if(token===pointToken)node.textContent='Radar point query unavailable: '+e.message+'. No water state is inferred.'}
  }
  function inspectCity(){if(point)inspect(point.lat,point.lon);else{const c=cities[cityIndex];if(c)inspect(c[2],c[3])}}
  function selectCity(i){cityIndex=i;point=null;inspectCity()}
  function showRadarDate(value){if(!metadata?.radar?.available||!dates(metadata.radar).includes(value))return false;source='radar';date=value;datePinned=true;paint();return true}
  function init(opts){map=opts.map;cities=opts.cities;for(const[p,z]of [['observedCoveragePane',365],['observedMaskPane',370],['observedPane',380]]){map.createPane(p);map.getPane(p).style.zIndex=z}
    el('observed-source').onchange=e=>{source=e.target.value;date='';datePinned=false;paint()};el('observed-date').onchange=e=>{if(dates().includes(e.target.value)){date=e.target.value;datePinned=true;paint()}};
    if(el('observed-latest'))el('observed-latest').onclick=()=>{datePinned=false;paint()};
    el('layer-observed').onchange=()=>{if(layer)el('layer-observed').checked?layer.addTo(map):map.removeLayer(layer);drawStatus()};el('layer-observed-coverage').onchange=()=>{if(coverage)el('layer-observed-coverage').checked?coverage.addTo(map):map.removeLayer(coverage);drawStatus()};
    if(el('layer-observed-exclusion'))el('layer-observed-exclusion').onchange=()=>{if(exclusion)el('layer-observed-exclusion').checked?exclusion.addTo(map):map.removeLayer(exclusion);drawStatus()};
  }
  return{init,refresh,inspect,selectCity,showRadarDate,checkFreshness:drawStatus,getState:state};
})();

